<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        const tileSize = 32;
        const tileWidth = canvas.width / tileSize;
        const tileHeight = canvas.height / tileSize;

        const plantTile = (x, y) => {
            tiles[`${x},${y}`] = { crop: null, stage: 0 };
        };

        const harvestTile = (x, y) => {
            const tile = tiles[`${x},${y}`];
            if (tile && tile.crop) {
                inventory.crops++;
                delete tiles[`${x},${y}`];
            }
        };

        const drawPlayer = () => {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);
        };

        const drawTiles = () => {
            for (const tile in tiles) {
                const [x, y] = tile.split(',');
                const tileData = tiles[tile];
                ctx.fillStyle = tileData.crop ? 'yellow' : 'gray';
                ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
            }
        };

        const drawInventory = () => {
            ctx.fillStyle = 'blue';
            ctx.font = '16px Arial';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        };

        const drawDay = () => {
            ctx.fillStyle = 'red';
            ctx.font = '16px Arial';
            ctx.fillText(`Day: ${day}`, 10, 60);
        };

        const update = () => {
            const dx = 0;
            const dy = 0;

            if (event.key === 'ArrowUp') dy -= 1;
            if (event.key === 'ArrowDown') dy += 1;
            if (event.key === 'ArrowLeft') dx -= 1;
            if (event.key === 'ArrowRight') dx += 1;

            player.x += dx;
            player.y += dy;

            if (player.x < 0) player.x = 0;
            if (player.x >= tileWidth) player.x = tileWidth - 1;
            if (player.y < 0) player.y = 0;
            if (player.y >= tileHeight) player.y = tileHeight - 1;

            if (event.key === 'p') plantTile(player.x, player.y);
            if (event.key === 't') day++;
            if (event.key === 'h') harvestTile(player.x, player.y);

            drawPlayer();
            drawTiles();
            drawInventory();
            drawDay();

            requestAnimationFrame(update);
        };

        document.addEventListener('keydown', update);

        window.game = { state: () => JSON.parse(JSON.stringify({ player, tiles, inventory, day })) };

        window.game = { state: () => JSON.parse(JSON.stringify({ player: {x: 0, y: 0}, tiles: {}, inventory: { seeds: 5, crops: 0 }, day: 0 })) };
    </script>
</body>
</html>
